function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var LABEL        = settings.label.value;         // small caption above the value ('' = none)
  var UNIT         = settings.unit.value;          // unit text under the value ('' = none)
  var MULTIPLIER   = settings.multiplier.value;    // value * multiplier (1 = as is; attitude decideg -> deg = 0.1, m/s -> km/h = 3.6)
  var DIGITS       = settings.digits.value;        // decimal places of the value
  var AUTO_RANGE   = settings.auto_range.value;    // scale from the whole-flight minimum and maximum (rounded outwards); off = Min / Max
  var MIN          = settings.min.value;           // left end of the bar (after the multiplier) when Auto range is off
  var MAX          = settings.max.value;           // right end of the bar (after the multiplier) when Auto range is off
  var SMOOTH_MS    = settings.smooth_ms.value;     // moving average window for the value in ms (0 = off)
  var TRACK_WIDTH  = settings.track_width.value;   // bar thickness at the default 320x190 size; scales with the widget
  var SHOW_LIMITS  = settings.show_limits.value;   // print Min and Max under the two ends of the bar
  var LIMIT_DIGITS = settings.limit_digits.value;  // decimal places of the Min / Max numbers
  var TRACK_COLOR  = settings.track_color.value;   // unfilled part of the bar
  var FILL_COLOR   = settings.fill_color.value;    // filled part of the bar (Min .. current value)
  var TEXT_COLOR   = settings.text_color.value;    // value / unit / caption color
  var LIMIT_COLOR  = settings.limit_color.value;   // Min / Max numbers color
  var FONT         = settings.font.value;          // font family
  var VALUE_SIZE   = settings.value_size.value;    // value font size at the default 320x190 size; scales with the widget
  var UNIT_SIZE    = settings.unit_size.value;     // unit font size at the default size; scales with the widget
  var LABEL_SIZE   = settings.label_size.value;    // caption font size at the default size; scales with the widget
  var LIMIT_SIZE   = settings.limit_size.value;    // Min / Max numbers font size at the default size; scales with the widget
  var SHADOW       = settings.text_shadow.value;   // CSS text shadow for all texts ('' = none)
  var BG           = settings.background.value;    // box background; alpha 0 = no box
  var RADIUS       = settings.radius.value;        // corner radius at the default size; scales with the widget
  var OPACITY      = settings.opacity.value;       // whole-widget opacity 0..1 (1 = opaque)
  // -------------------------------
  var W = ctx.width, H = ctx.height, s = ctx.state, i;
  var scale = Math.min(W / 320, H / 190);
  var col = ctx.columns[0];

  // ---- value (smoothed when asked; only inside the telemetry range) ----
  var raw = ctx.values[0], cur;
  if (typeof raw === 'number') {
    if (SMOOTH_MS > 0 && col) {
      var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 400) || [], sum = 0, cnt = 0;
      for (i = 0; i < sam.length; i++) if (typeof sam[i].v === 'number') { sum += sam[i].v; cnt++; }
      cur = cnt ? sum / cnt : raw;
    } else cur = raw;
    cur *= MULTIPLIER;
  }

  // ---- range ----
  var mn = MIN, mx = MAX;
  if (AUTO_RANGE && col) {
    var st = ctx.stats(col);
    if (st && st.count > 0) {
      var a = st.min * MULTIPLIER, b = st.max * MULTIPLIER;
      mn = Math.floor(Math.min(a, b)); mx = Math.ceil(Math.max(a, b));
    }
  }
  if (!(mx > mn)) mx = mn + 1;

  // ---- geometry: half circle, flat side down, centre on the flat side ----
  var p = 6 * scale, tw = TRACK_WIDTH * scale, fw = tw + 1.5 * scale;
  var fs = VALUE_SIZE * scale, ufs = UNIT_SIZE * scale, lfs = LABEL_SIZE * scale, nfs = LIMIT_SIZE * scale;
  var limH = SHOW_LIMITS ? nfs * 1.35 : 0;
  var Ro = Math.min(W / 2 - p - 1.5 * scale, H - p - limH - p);   // outer radius of the bar (fill is 1.5 px wider than the track)
  var Rt = Ro - tw / 2, cx = W / 2, cy = p + Ro;
  function pt(r, a) { var t = a * Math.PI / 180; return [(cx + r * Math.sin(t)).toFixed(2), (cy - r * Math.cos(t)).toFixed(2)]; }
  function ang(v) { return -90 + Math.max(0, Math.min(1, (v - mn) / (mx - mn))) * 180; }
  // one half-circle path shared by the track and the fill: the same curve, so the track never peeks out from under the fill
  var p1 = pt(Rt, -90), p2 = pt(Rt, 90);
  var path = 'M' + p1[0] + ',' + p1[1] + ' A' + Rt.toFixed(2) + ',' + Rt.toFixed(2) + ' 0 0 1 ' + p2[0] + ',' + p2[1];
  var uid = (s.uid || (s.uid = 'u' + Math.random().toString(36).slice(2, 8))) + (s.frame = ((s.frame || 0) + 1) % 1000000);
  function fmt(v, d) { return v.toFixed(d); }

  // ---- static part: track + limit numbers (built once per size / look) ----
  var staticKey = W + 'x' + H + '|' + mn + '|' + mx + '|' + tw + '|' + TRACK_COLOR + '|' + LIMIT_COLOR + '|' + nfs + '|' + SHOW_LIMITS + '|' + LIMIT_DIGITS;
  if (s.staticKey !== staticKey) {
    var sv = '<path d="' + path + '" fill="none" stroke="' + TRACK_COLOR + '" stroke-width="' + tw.toFixed(2) + '" stroke-linecap="butt"/>';
    if (SHOW_LIMITS) {
      var ny = (cy + nfs * 0.75).toFixed(2);
      sv += '<text x="' + (cx - Rt).toFixed(2) + '" y="' + ny + '" fill="' + LIMIT_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central">' + fmt(mn, LIMIT_DIGITS) + '</text>'
        + '<text x="' + (cx + Rt).toFixed(2) + '" y="' + ny + '" fill="' + LIMIT_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central">' + fmt(mx, LIMIT_DIGITS) + '</text>';
    }
    s.staticSvg = sv; s.staticKey = staticKey;
  }

  // ---- dynamic part: fill = the same path under a wedge clip (only the wedge's radial edge moves with the value) ----
  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="display:block;font-family:' + FONT + ';opacity:' + OPACITY
    + ';background:' + BG + ';border-radius:' + (RADIUS * scale).toFixed(1) + 'px">' + s.staticSvg;
  if (typeof cur === 'number') {
    var ac = ang(cur); if (ac >= 89.95) ac = 110;   // at Max the wedge edge would sit exactly on the butt end: open it fully
    if (ac + 90 >= 0.05) {
      var Rf = Ro * 1.3, a1 = -110, n = Math.max(1, Math.ceil((ac - a1) / 45)), d = 'M' + cx.toFixed(2) + ',' + cy.toFixed(2), q;
      for (i = 0; i <= n; i++) { q = pt(Rf, a1 + (ac - a1) * i / n); d += ' L' + q[0] + ',' + q[1]; }
      out += '<defs><clipPath id="' + uid + '"><path d="' + d + ' Z"/></clipPath></defs>'
        + '<path d="' + path + '" fill="none" stroke="' + FILL_COLOR + '" stroke-width="' + fw.toFixed(2) + '" stroke-linecap="butt" clip-path="url(#' + uid + ')"/>';
    }
  }
  // ---- centre stack inside the half disc, bottom to top: unit on the flat side, value above it, caption above the value ----
  var shadow = SHADOW ? ' style="text-shadow:' + SHADOW + '"' : '';
  var uy = cy - ufs * 0.55;                                        // unit centre
  var vy = (UNIT ? uy - ufs * 0.55 : cy) - fs * 0.5;               // value centre
  var ly = vy - fs * 0.55 - lfs * 0.5;                             // caption centre
  if (LABEL) out += '<text x="' + cx + '" y="' + ly.toFixed(2) + '" fill="' + TEXT_COLOR + '" fill-opacity=".75" font-size="' + lfs.toFixed(1) + '" font-weight="bold" letter-spacing="' + (1.5 * scale).toFixed(1) + '" text-anchor="middle" dominant-baseline="central"' + shadow + '>' + LABEL + '</text>';
  out += '<text x="' + cx + '" y="' + vy.toFixed(2) + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" text-anchor="middle" dominant-baseline="central"' + shadow + '>' + (typeof cur === 'number' ? fmt(cur, DIGITS) : '--') + '</text>';
  if (UNIT) out += '<text x="' + cx + '" y="' + uy.toFixed(2) + '" fill="' + TEXT_COLOR + '" fill-opacity=".85" font-size="' + ufs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central"' + shadow + '>' + UNIT + '</text>';
  out += '</svg>';
  return out;
}
